      ],
      "support_status": "SUFFICIENT",
      "rationale": "P020 explicitly assigns clarified histories this role when the causal-support conditions are absent."
    }
  },
  "signal_basis": {
    "component_id": "C041.signal_basis",
    "value": "Histories are inspected and gaps clarified with participants while preserving original records. A within-window publication difference is observed, but the stated causal-support conditions do not hold, so it is treated as an association.",
    "scope": "Assumed occurrence of the proposed observations; failed checks or sparse evidence require retaining uncertainty and continuing targeted follow-up or observation.",
