        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the clarification operation, proposed publication observation, association-only interpretation and limits on proceeding."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C041.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its exploratory scope; no unresolved empirical relation is needed to license it."
    }
  },
  "rationale": "Clarified histories can inform what to investigate next without establishing why publication changed. The claim licenses further testing, while explicitly retaining the association-only interpretation.",
  "uncertainty": "The histories do not establish a release effect or guarantee that subsequent testing will confirm an explanation.",
  "anomalies": []
